while (tender && tender.body) { tender = tender.body; }
if (tender && tender.tender) { tender = { ...tender, ...tender.tender }; }

const buyer = (tender && tender.buyer) || 'Organisme Public Tunisien';
const country = (tender && tender.country) || 'Tunisia';
const desc = (tender && (tender.description || tender.title)) || "Modernisation du système d'information et services numériques";
const id = (tender && (tender.id || tender.tender_id)) || 'AO-2026-001';

const buyerQuery = `"${buyer}" ${country} IT projects technology budget`;
const sectorQuery = `"${buyer}" digital transformation software`;

return [{
  json: {
    id,
    tender_id: id,
    buyer,
    country,
    description: desc,
    source: (tender && tender.source) || 'appeloffres.com',
    url: (tender && tender.url) || '',
    published_date: (tender && tender.published_date) || '',
    deadline: (tender && tender.deadline) || '',
    search_query_1: buyerQuery,
    search_query_2: sectorQuery
  }
}];

