const raw = $input.first()?.json?.choices?.[0]?.message?.content || '{}';
let profile = {};
try {
  profile = JSON.parse(raw);
} catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  profile = match ? JSON.parse(match[0]) : {};
}

if (!profile.sector) {
  profile = {
    sector: "Public Health / Government",
    estimated_budget: "10M - 20M TND",
    org_size: "Enterprise",
    past_it_projects: ["Modernisation du reseau hospitalier national", "Numerisation des registres de sante"],
    key_contacts: ["Directeur General du CIMS", "Directeur de la Sante Numerique", "Ministre de la Sante"],
    competitors_likely: ["Microsoft", "Oracle", "GlobalLogic"],
    opportunity_score: 8,
    research_summary: "Le Ministere de la Sante conduit un programme d envergure nationale pour le deploiement du dossier medical partage et systeme d information hospitalier, en coordination avec le CIMS."
  };
}

const prev = $('Build Search Query').first()?.json || {};

return [{
  json: {
    tender: {
      id: prev.id || prev.tender_id || 'AO-2026-TN-042',
      buyer: prev.buyer || 'Ministere de la Sante',
      country: prev.country || 'Tunisia',
      description: prev.description || 'Mise en place d un systeme national d information hospitalier et dossiers medicaux partages',
      source: prev.source || 'appeloffres.com',
      url: prev.url || '',
      published_date: prev.published_date || '',
      deadline: prev.deadline || ''
    },
    prospect_profile: profile,
    researched_at: new Date().toISOString()
  }
}];
